actions.script:
const out = ec.service.sync().name('mantle.party.ConsentServices.resolve#UnsubscribeToken').parameters({token: token || ''}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
ec.web.sendJsonResponse({valid: true, organizationName: out.organizationName ?? null, contactListId: out.contactListId ?? null,
    contactListName: out.contactListName ?? null, listDescription: out.listDescription ?? null, statusId: out.statusId ?? null,
    subscribed: !!out.subscribed, unsubscribePending: !!out.unsubscribePending, maskedAddress: out.maskedAddress ?? null,
    marketingWithdrawn: !!out.marketingWithdrawn, listList: Array.from(out.listList || [])})

let baseUrl = null
try { baseUrl = ec.web.getWebappRootUrl() || null } catch (err) { baseUrl = null }
const out = ec.service.sync().name('mantle.party.ConsentServices.unsubscribe#ContactListParty').parameters({token: token || '',
    allMarketing: choice === 'all', reasonText: reasonText || null, verifyCode: verifyCode || null, baseUrl: baseUrl}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
ec.web.sendJsonResponse({statusId: out.statusId ?? null, unsubscribePending: !!out.unsubscribePending, verifyEmailSent: !!out.verifyEmailSent,
    marketingWithdrawn: !!out.marketingWithdrawn, changedList: Array.from(out.changedList || []),
    failedContactListIds: Array.from(out.failedContactListIds || [])})

let choices = []
try { choices = JSON.parse(String(listChoices || '[]')) } catch (err) { choices = [] }
if (!Array.isArray(choices)) choices = []
let baseUrl = null
try { baseUrl = ec.web.getWebappRootUrl() || null } catch (err) { baseUrl = null }
const out = ec.service.sync().name('mantle.party.ConsentServices.apply#UnsubscribePreferences').parameters({token: token || '',
    listChoices: choices.map((choice) => ({contactListId: String(choice && choice.contactListId || ''), subscribed: !!(choice && choice.subscribed)})),
    reasonText: reasonText || null, baseUrl: baseUrl}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
ec.web.sendJsonResponse({changedList: Array.from(out.changedList || []), failedContactListIds: Array.from(out.failedContactListIds || []),
    unsubscribePending: !!out.unsubscribePending, verifyEmailSent: !!out.verifyEmailSent})

const field = context.get('List-Unsubscribe') || context.get('listUnsubscribe') || ''
if (String(field).trim().toLowerCase() !== 'one-click') {
    ec.web.sendJsonError(400, ec.l10n.localize('A one-click unsubscribe posts List-Unsubscribe=One-Click')); return }
// in a transaction of its own, so a refused token leaves this request a plain answer
ec.message.pushErrors()
let refused = false
try {
    ec.service.sync().name('mantle.party.ConsentServices.unsubscribe#ContactListParty').parameters({token: token || '',
        listUnsubscribe: 'One-Click'}).requireNewTransaction(true).call()
    refused = ec.message.hasError()
} catch (err) {
    refused = true
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (refused) { ec.web.sendJsonError(410, ec.l10n.localize('This unsubscribe link is not valid or has expired')); return }
ec.web.sendTextResponse(ec.l10n.localize('You are unsubscribed.'), 'text/plain', null)
